package com.example.expensetracker.model;

import java.math.BigDecimal;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;

/**
 * Entity class representing an Expense in the database.
 * 
 * `@Entity` specifies that the class is a JPA entity and is mapped to a database table.
 */
@Entity
public class Expense {

    /**
     * Unique identifier for each expense.
     * 
     * `@Id` designates the primary key of this entity.
     * `@GeneratedValue(strategy = GenerationType.IDENTITY)` specifies that the primary key value 
     * is automatically generated by the database using an identity column (auto-increment).
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * Brief description of the expense.
     */
    private String description;

    /**
     * Monetary cost of the expense. Uses BigDecimal for accurate financial calculations.
     */
    private BigDecimal amount;

    /**
     * Gets the unique ID of the expense.
     *
     * @return the expense ID
     */
    public Long getId() {
        return id;
    }

    /**
     * Sets the unique ID of the expense.
     *
     * @param id the new expense ID
     */
    public void setId(Long id) {
        this.id = id;
    }

    /**
     * Gets the description of the expense.
     *
     * @return the expense description
     */
    public String getDescription() {
        return description;
    }

    /**
     * Sets the description of the expense.
     *
     * @param description the new expense description
     */
    public void setDescription(String description) {
        this.description = description;
    }

    /**
     * Gets the monetary amount of the expense.
     *
     * @return the expense amount
     */
    public BigDecimal getAmount() {
        return amount;
    }

    /**
     * Sets the monetary amount of the expense.
     *
     * @param amount the new expense amount
     */
    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }
}